"""
    Transforma os valores dos club
    DIAMANTE -> 1
    OURO -> 2
    PRATA -> 3
    BRONZE -> 4
    """
def handle_club(input: str) -> int {
    if (input == "DIAMANTE") {
        return 1;
    } elif (input == "OURO") {
        return 2;
    } elif (input == "PRATA") {
        return 3;
    } elif (input == "BRONZE") {
        return 4;
    }
    raise ValueError(f"Club ({input}) desconhecido, verifique");
}

